/* @lc app=leetcode id=1938 lang=kotlin */
class Solution { fun maxGeneticDifference(parents: IntArray, queries: Array<IntArray>): IntArray = IntArray(3600005 * 2).let { next -> IntArray(3600005).let { count -> intArrayOf(1).let { alloc -> Array(parents.size) { ArrayList<Int>() }.let { adj -> Array(parents.size) { ArrayList<Pair<Int, Int>>() }.let { q -> IntArray(queries.size).let { ans -> { num: Int, delta: Int -> (17 downTo 0).fold(0) { curr, i -> ((num shr i) and 1).let { bit -> (if (next[curr * 2 + bit] == 0) next[curr * 2 + bit] = alloc[0].also { alloc[0]++ } else 0).run { next[curr * 2 + bit] } }.also { count[it] += delta } } }.let { change -> { num: Int -> (17 downTo 0).fold(0 to 0) { (curr, ansVal), i -> ((num shr i) and 1).let { bit -> (bit xor 1).let { want -> if (next[curr * 2 + want] != 0 && count[next[curr * 2 + want]] > 0) next[curr * 2 + want] to (ansVal or (1 shl i)) else next[curr * 2 + bit] to ansVal } } }.second }.let { query -> DeepRecursiveFunction<Int, Unit> { u -> change(u, 1).let { q[u].forEach { ans[it.first] = query(it.second) } }.run { adj[u].forEach { callRecursive(it) } }.run { change(u, -1) } }.let { dfs -> parents.indices.forEach { i -> if (parents[i] != -1) adj[parents[i]].add(i) }.run { queries.indices.forEach { i -> q[queries[i][0]].add(Pair(i, queries[i][1])) } }.run { dfs(parents.indexOf(-1)) }.run { ans } } } } } } } } } }